  1	<!--
  2	  AC: @ui-workflows-view ac-1 — Each workflow shows id, description, ordered steps with names,
  3	  trigger type if configured, and loop variant indicator. A Start button initiates the workflow
  4	  via daemon API.
  5	-->
  6	<script lang="ts">
  7		import { onMount, onDestroy } from 'svelte';
  8		import type { Workflow } from '@kynetic-ai/shared';
  9		import { fetchWorkflows } from '$lib/api';
 10		import { isStaticMode } from '$lib/stores/mode.svelte';
 11		import { subscribe, unsubscribe, on, off } from '$lib/stores/connection.svelte';
 12		import { getProjectVersion } from '$lib/stores/project.svelte';
 13		import { Card, CardContent, CardHeader } from '$lib/components/ui/card';
 14		import { Badge } from '$lib/components/ui/badge';
 15		import { Button } from '$lib/components/ui/button';
 16		import WorkflowIcon from '@lucide/svelte/icons/workflow';
 17		import PlayIcon from '@lucide/svelte/icons/play';
 18		import ZapIcon from '@lucide/svelte/icons/zap';
 19		import RepeatIcon from '@lucide/svelte/icons/repeat';
 20		import CheckCircleIcon from '@lucide/svelte/icons/check-circle';
 21		import CircleDotIcon from '@lucide/svelte/icons/circle-dot';
 22		import CircleIcon from '@lucide/svelte/icons/circle';
 23		import CopyIcon from '@lucide/svelte/icons/copy';
 24	
 25		// ── Data state ──
 26		let workflows = $state<Workflow[]>([]);
 27		let loading = $state(true);
 28		let error = $state('');
 29		let copiedId = $state<string | null>(null);
 30	
 31		// ── Step type classes (using design-system severity tokens) ──
 32		const STEP_TYPE_CLASS: Record<string, string> = {
 33			action: 'text-severity-success',
 34			check: 'text-severity-info',
 35			decision: 'text-severity-warning'
 36		};
 37	
 38		// ── Lifecycle ──
 39		onMount(async () => {
 40			await loadData();
 41	
 42			if (!isStaticMode()) {
 43				subscribe(['files:updates']);
 44				on('files:updates', handleUpdate);
 45			}
 46		});
 47	
 48		onDestroy(() => {
 49			if (!isStaticMode()) {
 50				off('files:updates', handleUpdate);
 51				unsubscribe(['files:updates']);
 52			}
 53		});
 54	
 55		// Reload on project change
 56		$effect(() => {
 57			const version = getProjectVersion();
 58			if (version > 0) {
 59				loadData();
 60			}
 61		});
 62	
 63		// ── Data loading ──
 64		async function loadData() {
 65			try {
 66				loading = true;
 67				error = '';
 68				const response = await fetchWorkflows();
 69				workflows = response.items;
 70			} catch (err) {
 71				error = err instanceof Error ? err.message : 'Failed to load workflows';
 72			} finally {
 73				loading = false;
 74			}
 75		}
 76	
 77		// ── WebSocket handler ──
 78		function handleUpdate() {
 79			loadData();
 80		}
 81	
 82		// ── Copy start command ──
 83		async function copyStartCommand(workflowId: string) {
 84			const command = `kspec workflow start @${workflowId}`;
 85			try {
 86				await navigator.clipboard.writeText(command);
 87				copiedId = workflowId;
 88				setTimeout(() => {
 89					copiedId = null;
 90				}, 2000);
 91			} catch {
 92				// Clipboard API may not be available
 93			}
 94		}
 95	</script>
 96	
 97	<div class="flex flex-col gap-4 p-6">
 98		<!-- Header -->
 99		<div class="flex items-center justify-between">
100			<div>
101				<h1 class="text-2xl font-bold">Workflows</h1>
102				{#if !loading}
103					<p class="text-sm text-muted-foreground" data-testid="workflows-summary">
104						{workflows.length} workflow{workflows.length === 1 ? '' : 's'} defined
105					</p>
106				{/if}
107			</div>
108		</div>
109	
110		{#if error}
111			<div class="bg-destructive/10 text-destructive p-4 rounded-lg text-sm" data-testid="workflows-error" role="alert">
112				{error}
113			</div>
114		{/if}
115	
116		<!-- Workflows list -->
117		{#if loading}
118			<div class="flex flex-col gap-3" data-testid="workflows-loading">
119				{#each Array(3) as _}
120					<div class="h-36 rounded-lg bg-muted ds-shimmer"></div>
121				{/each}
122			</div>
123		{:else if workflows.length === 0}
124			<!-- AC: @ui-workflows-view ac-1 — Empty state -->
125			<div class="flex flex-col items-center justify-center py-16" data-testid="workflows-empty">
126				<WorkflowIcon class="size-12 text-muted-foreground/30 mb-4" />
127				<h2 class="text-lg font-medium text-muted-foreground mb-1">No workflows defined</h2>
128				<p class="text-sm text-muted-foreground">
129					{#if isStaticMode()}
130						No workflow data available in the snapshot.
131					{:else}
132						Define workflows in <code class="text-xs bg-muted px-1 py-0.5 rounded">kynetic.meta.yaml</code> to see them here.
133					{/if}
134				</p>
135			</div>
136		{:else}
137			<!-- AC: @ui-workflows-view ac-1 — Workflow cards with all required fields -->
138			<div class="flex flex-col gap-3" data-testid="workflows-list">
139				{#each workflows as workflow (workflow._ulid)}
140					<Card class="transition-all duration-200 hover:shadow-md" data-testid="workflow-card">
141						<CardHeader class="pb-3">
142							<div class="flex items-start justify-between gap-4">
143								<div class="flex-1 min-w-0">
144									<div class="flex items-center gap-2 mb-1 flex-wrap">
145										<h3 class="text-sm font-semibold" data-testid="workflow-id">
146											{workflow.id}
147										</h3>
148										<!-- AC: @ui-workflows-view ac-1 — Trigger type badge -->
149										<Badge variant="secondary" class="text-xs gap-1" data-testid="workflow-trigger">
150											<ZapIcon class="h-3 w-3" />
151											{workflow.trigger}
152										</Badge>
153										<!-- AC: @ui-workflows-view ac-1 — Loop variant indicator -->
154										{#if workflow.mode === 'loop'}
155											<Badge variant="outline" class="text-xs gap-1" data-testid="workflow-loop">
156												<RepeatIcon class="h-3 w-3" />
157												Loop
158											</Badge>
159										{/if}
160										{#if workflow.based_on}
161											<Badge variant="outline" class="text-xs gap-1" data-testid="workflow-variant">
162												variant of @{workflow.based_on}
163											</Badge>
164										{/if}
165										{#if workflow.enforcement === 'strict'}
166											<Badge class="text-xs bg-status-blocked text-status-blocked-fg">
167												Strict
168											</Badge>
169										{/if}
170									</div>
171									{#if workflow.description}
172										<p class="text-sm text-muted-foreground whitespace-pre-line" data-testid="workflow-description">
173											{workflow.description.trim()}
174										</p>
175									{/if}
176								</div>
177								<!-- AC: @ui-workflows-view ac-1 — Start button -->
178								{#if !isStaticMode()}
179									<Button
180										variant="outline"
181										size="sm"
182										class="h-8 gap-1.5 text-xs shrink-0"
183										data-testid="workflow-start-btn"
184										onclick={() => copyStartCommand(workflow.id)}
185									>
186										{#if copiedId === workflow.id}
187											<CopyIcon class="size-3.5" />
188											Copied!
189										{:else}
190											<PlayIcon class="size-3.5" />
191											Start
192										{/if}
193									</Button>
194								{/if}
195							</div>
196						</CardHeader>
197						<CardContent class="pt-0">
198							<!-- AC: @ui-workflows-view ac-1 — Ordered steps with names -->
199							{#if workflow.steps.length > 0}
200								<div class="flex flex-col gap-1.5" data-testid="workflow-steps">
201									<h4 class="text-xs font-medium text-muted-foreground uppercase tracking-wider">
202										Steps ({workflow.steps.length})
203									</h4>
204									<ol class="flex flex-col gap-1">
205										{#each workflow.steps as step, i}
206											<li class="flex items-start gap-2 text-sm" data-testid="workflow-step">
207												<span class="flex items-center gap-1.5 shrink-0 mt-0.5">
208													<span class="text-xs text-muted-foreground font-mono w-4 text-right">{i + 1}.</span>
209													{#if step.type === 'check'}
210														<CheckCircleIcon class="size-3.5 {STEP_TYPE_CLASS.check}" />
211													{:else if step.type === 'decision'}
212														<CircleDotIcon class="size-3.5 {STEP_TYPE_CLASS.decision}" />
213													{:else}
214														<CircleIcon class="size-3.5 {STEP_TYPE_CLASS.action}" />
215													{/if}
216												</span>
217												<span class="min-w-0">
218													<span class="text-muted-foreground">{step.content}</span>
219													{#if step.on_fail}
220														<span class="text-xs text-destructive/80 ml-1">(on fail: {step.on_fail})</span>
221													{/if}
222													{#if step.options && step.options.length > 0}
223														<ul class="mt-1 ml-4 space-y-0.5">
224															{#each step.options as option}
225																<li class="text-xs text-muted-foreground list-disc">{option}</li>
226															{/each}
227														</ul>
228													{/if}
229												</span>
230											</li>
231										{/each}
232									</ol>
233								</div>
234							{:else}
235								<p class="text-xs text-muted-foreground italic">No steps defined</p>
236							{/if}
237	
238							<!-- Metadata row -->
239							<div class="flex items-center gap-2 text-xs text-muted-foreground mt-3 pt-3 border-t">
240								<code class="bg-muted px-1 py-0.5 rounded" data-testid="workflow-ulid">
241									{workflow._ulid.slice(0, 8)}
242								</code>
243								{#if workflow.tags && workflow.tags.length > 0}
244									<span>&middot;</span>
245									{#each workflow.tags as tag}
246										<Badge variant="secondary" class="text-xs">{tag}</Badge>
247									{/each}
248								{/if}
249							</div>
250						</CardContent>
251					</Card>
252				{/each}
253			</div>
254		{/if}
255	</div>

