 28	/**
 29	 * Convert ExportedTask to TaskSummary
 30	 */
 31	function toTaskSummary(task: ExportedTask): TaskSummary {
 32		return {
 33			_ulid: task._ulid,
 34			slugs: task.slugs,
 35			title: task.title,
 36			type: task.type,
 37			status: task.status,
 38			priority: task.priority,
 39			spec_ref: task.spec_ref ?? undefined,
 40			tags: task.tags,
 41			depends_on: task.depends_on,
 42			created_at: task.created_at,
 43			started_at: task.started_at ?? undefined,
 44			notes_count: task.notes?.length ?? 0,
 45			todos_count: task.todos?.length ?? 0
 46		};
 47	}
