 50	 * Convert ExportedItem to ItemSummary
 51	 */
 52	function toItemSummary(item: ExportedItem): ItemSummary {
 53		return {
 54			_ulid: item._ulid,
 55			slugs: item.slugs,
 56			title: item.title,
 57			type: item.type,
 58			status: item.status,
 59			tags: item.tags,
 60			created_at: item.created_at ?? new Date().toISOString()
 61		};
 62	}
 63	
 64	/**
 65	 * Filter helper for tasks
 66	 */
 67	function filterTasks(
 68		tasks: ExportedTask[],
 69		params?: {
 70			status?: string;
 71			type?: string;
 72			tag?: string;
 73			assignee?: string;
 74			automation?: string;
 75		}
 76	): ExportedTask[] {
 77		let result = tasks;
 78	
 79		if (params?.status) {
 80			result = result.filter((t) => t.status === params.status);
 81		}
 82		if (params?.type) {
 83			result = result.filter((t) => t.type === params.type);
 84		}
 85		if (params?.tag) {
 86			result = result.filter((t) => t.tags.includes(params.tag!));
 87		}
 88		if (params?.assignee) {
 89			result = result.filter((t) => t.assignee === params.assignee);
 90		}
 91		if (params?.automation) {
 92			result = result.filter((t) => t.automation === params.automation);
 93		}
 94	
 95		return result;
 96	}
 97	
 98	/**
 99	 * Filter helper for items
100	 */
101	function filterItems(
102		items: ExportedItem[],
103		params?: {
104			type?: string | string[];
105			tag?: string;
106		}
107	): ExportedItem[] {
108		let result = items;
109	
110		if (params?.type) {
111			const types = Array.isArray(params.type) ? params.type : [params.type];
112			result = result.filter((i) => types.includes(i.type));
113		}
114		if (params?.tag) {
115			result = result.filter((i) => i.tags.includes(params.tag!));
116		}
117	
118		return result;
