121	/**
122	 * Paginate array
123	 */
124	function paginate<T>(
125		items: T[],
126		params?: { limit?: number; offset?: number }
127	): PaginatedResponse<T> {
128		const limit = params?.limit ?? 50;
129		const offset = params?.offset ?? 0;
130		const paged = items.slice(offset, offset + limit);
131	
132		return {
133			items: paged,
134			total: items.length,
135			offset,
136			limit
137		};
138	}
139	
140	/**
141	 * Find task by reference (slug or ULID prefix)
142	 * AC: @gh-pages-export ac-12
143	 */
144	function findTaskByRef(tasks: ExportedTask[], ref: string): ExportedTask | null {
145		const normalizedRef = ref.startsWith('@') ? ref.slice(1) : ref;
146	
147		// Try exact slug match first
148		const bySlug = tasks.find((t) => t.slugs.includes(normalizedRef));
149		if (bySlug) return bySlug;
150	
151		// Try ULID prefix match
152		const byUlid = tasks.find((t) => t._ulid.startsWith(normalizedRef.toUpperCase()));
153		if (byUlid) return byUlid;
154	
155		return null;
156	}
157	
158	/**
159	 * Find item by reference (slug or ULID prefix)
160	 * AC: @gh-pages-export ac-13
161	 */
162	function findItemByRef(items: ExportedItem[], ref: string): ExportedItem | null {
163		const normalizedRef = ref.startsWith('@') ? ref.slice(1) : ref;
164	
165		// Try exact slug match first
166		const bySlug = items.find((i) => i.slugs.includes(normalizedRef));
167		if (bySlug) return bySlug;
168	
169		// Try ULID prefix match
170		const byUlid = items.find((i) => i._ulid.startsWith(normalizedRef.toUpperCase()));
171		if (byUlid) return byUlid;
172	
173		return null;
174	}
