178	// ============================================================
179	
180	/**
181	 * Fetch tasks from static snapshot
182	 * AC: @gh-pages-export ac-11
183	 */
184	export function fetchTasksStatic(params?: {
185		status?: string;
186		type?: string;
187		tag?: string;
188		assignee?: string;
189		automation?: string;
190		limit?: number;
191		offset?: number;
192	}): PaginatedResponse<TaskSummary> {
193		const snapshot = getSnapshot();
194		if (!snapshot) {
195			return { items: [], total: 0, offset: 0, limit: 50 };
196		}
197	
198		const filtered = filterTasks(snapshot.tasks, params);
199		const paginated = paginate(filtered, params);
200	
201		return {
202			...paginated,
203			items: paginated.items.map(toTaskSummary)
204		};
205	}
206	
207	/**
208	 * Fetch single task from static snapshot
209	 * AC: @gh-pages-export ac-12
210	 */
211	export function fetchTaskStatic(ref: string): TaskDetail | null {
212		const snapshot = getSnapshot();
213		if (!snapshot) return null;
214	
215		const task = findTaskByRef(snapshot.tasks, ref);
216		if (!task) return null;
217	
218		// ExportedTask extends TaskDetail, so we can return it directly
219		return task;
220	}
221	
222	/**
223	 * Fetch items from static snapshot
224	 * AC: @gh-pages-export ac-11
225	 */
226	export function fetchItemsStatic(params?: {
227		type?: string | string[];
228		tag?: string;
