235		}
236	
237		const filtered = filterItems(snapshot.items, params);
238		const paginated = paginate(filtered, params);
239	
240		return {
241			...paginated,
242			items: paginated.items.map(toItemSummary)
243		};
244	}
245	
246	/**
247	 * Fetch single item from static snapshot
248	 * AC: @gh-pages-export ac-13
249	 */
250	export function fetchItemStatic(ref: string): ItemDetail | null {
251		const snapshot = getSnapshot();
252		if (!snapshot) return null;
253	
254		const item = findItemByRef(snapshot.items, ref);
255		if (!item) return null;
256	
257		return item;
258	}
